/** Project [lng, lat] onto the map's pixel space (clamped to the visible latitude band). */
export function project(lng: number, lat: number): [number, number] {
  const x = ((lng + 180) / 360) * MAP_W;
  const y = Math.min(MAP_H - 2, Math.max(2, ((MAP.latMax - lat) / (MAP.step * MAP.rows)) * MAP_H));
  return [x, y];
}
